                f"Your total spend with us is {r['spend']}, and we'd love to welcome you back.\n\nCheers,\nThe Customer Success Team")
        raw = base64.urlsafe_b64encode(json.dumps({"To": r["email"], "Subject": r["subject"], "Body": body}).encode()).decode()
        try:
